const locales = {
  ru: "ru-RU", en: "en-US", ig: "ig-NG", uz: "uz-UZ", uk: "uk-UA", he: "he-IL", yi: "yi",
};

let currentLanguage = "ru";

export function setLanguage(language) {
  currentLanguage = dictionaries[language] ? language : "ru";
  if (typeof document !== "undefined") {
    document.documentElement.lang = currentLanguage;
    document.documentElement.dir = ["he", "yi"].includes(currentLanguage) ? "rtl" : "ltr";
  }
}

export function getLanguage() {
  return currentLanguage;
}

export function getLocale() {
  return locales[currentLanguage] ?? locales.ru;
}

export function getTranslationKeys(language = "ru") {
  return Object.keys(dictionaries[language] ?? {});
}

export function hasTranslation(language, key) {
  return typeof dictionaries[language]?.[key] === "string" && dictionaries[language][key].length > 0;
}

export function t(key, variables = {}) {
  const template = dictionaries[currentLanguage]?.[key] ?? dictionaries.ru[key] ?? key;
  return Object.entries(variables).reduce(
    (value, [name, replacement]) => value.replaceAll(`{${name}}`, String(replacement)),
    template,
  );
}

export function translateDocument(root = document) {
  document.title = t("app.title");
  root.querySelectorAll("[data-i18n]").forEach((element) => {
    element.textContent = t(element.dataset.i18n);
  });
  root.querySelectorAll("[data-i18n-placeholder]").forEach((element) => {
    element.placeholder = t(element.dataset.i18nPlaceholder);
  });
  root.querySelectorAll("[data-i18n-aria]").forEach((element) => {
    element.setAttribute("aria-label", t(element.dataset.i18nAria));
  });
  root.querySelectorAll("[data-i18n-title]").forEach((element) => {
    element.title = t(element.dataset.i18nTitle);
  });
}
